BEGIN;
CREATE TABLE IF NOT EXISTS public.site_services (
 id text PRIMARY KEY DEFAULT 'main' CHECK (id = 'main'),
 title text NOT NULL,
 text text NOT NULL,
 cards jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(cards) = 'array' AND jsonb_array_length(cards) <= 12),
 media_cleanup_paths jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(media_cleanup_paths) = 'array'),
 revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.site_services ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_services FROM anon, authenticated;
GRANT SELECT ON public.site_services TO anon, authenticated;
GRANT ALL ON public.site_services TO service_role;
CREATE POLICY "Services are public" ON public.site_services FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.site_services (id,title,text,cards) VALUES ('main','Услуги','Полный спектр профессиональных услуг по техническому обслуживанию, проектированию и аудиту современных инженерных систем, а также обеспечению комплексной безопасности объектов.','[{"id":"security","sortOrder":10,"iconFilename":"shield.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\" d=\"M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z\"/></svg>","title":"Комплексные системы обеспечения безопасности (КСОБ)","text":"Проектирование, монтаж и интеграция современных охранных систем, контроля доступа и видеонаблюдения для объектов любой сложности."},{"id":"heat","sortOrder":20,"iconFilename":"flame.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\" d=\"M12 3q1 4 4 6.5t3 5.5a1 1 0 0 1-14 0a5 5 0 0 1 1-3a1 1 0 0 0 5 0c0-2-1.5-3-1.5-5q0-2 2.5-4\"/></svg>","title":"Теплоэнергетика и учёт","text":"Установка, пусконаладка и модернизация индивидуальных тепловых пунктов (ИТП) и систем точного приборного учёта тепловой энергии."},{"id":"electricity","sortOrder":30,"iconFilename":"plug.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\" d=\"M12 22v-5m3-9V2m2 6a1 1 0 0 1 1 1v4a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V9a1 1 0 0 1 1-1zM9 8V2\"/></svg>","title":"Электролаборатория и измерения","text":"Полный комплекс испытаний электрооборудования, замеры сопротивления изоляции, диагностика сетей и выдача официальных заключений."},{"id":"sewer","sortOrder":40,"iconFilename":"circle-dot.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\"><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"10\"/></g></svg>","title":"Обслуживание канализационных систем","text":"Полный комплекс испытаний электрооборудования, замеры сопротивления изоляции, диагностика сетей и выдача официальных заключений."},{"id":"kitchen","sortOrder":50,"iconFilename":"microwave.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\"><rect width=\"20\" height=\"15\" x=\"2\" y=\"4\" rx=\"2\"/><rect width=\"8\" height=\"7\" x=\"6\" y=\"8\" rx=\"1\"/><path d=\"M18 8v7M6 19v2m12-2v2\"/></g></svg>","title":"Обслуживание технологического оборудования пищеблоков","text":"Технический сервис, диагностика и профессиональный ремонт теплового, холодильного и электромеханического оборудования кухонь."},{"id":"fire","sortOrder":60,"iconFilename":"fire-extinguisher.svg","iconPath":null,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" color=\"#2a9ccf\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.25\"><path d=\"M15 6.5V3a1 1 0 0 0-1-1h-2a1 1 0 0 0-1 1v3.5M9 18h8m1-15h-3\"/><path d=\"M11 3a6 6 0 0 0-6 6v11m0-7h4m8-3a4 4 0 0 0-8 0v10a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2Z\"/></g></svg>","title":"Противопожарные мероприятия","text":"Разработка планов эвакуации, установка систем автоматического пожаротушения, монтаж сигнализаций и огнезащитная обработка."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
-- Route existing standard navigation items to the new page, preserving custom links.
UPDATE public.site_header SET menu_items = (SELECT jsonb_agg(CASE WHEN item->>'id' = 'services' AND item->>'href' IN ('/#services','#services') THEN jsonb_set(item,'{href}','"/services"') ELSE item END ORDER BY position) FROM jsonb_array_elements(menu_items) WITH ORDINALITY AS items(item,position)), revision = revision + 1, updated_at = now() WHERE menu_items @> '[{"id":"services","href":"/#services"}]'::jsonb OR menu_items @> '[{"id":"services","href":"#services"}]'::jsonb;
UPDATE public.site_footer SET columns = (SELECT jsonb_agg(jsonb_set(col,'{items}',(SELECT jsonb_agg(CASE WHEN item->>'id' = 'services' AND item->>'href' IN ('/#services','#services') THEN jsonb_set(item,'{href}','"/services"') ELSE item END ORDER BY item_position) FROM jsonb_array_elements(col->'items') WITH ORDINALITY AS items(item,item_position))) ORDER BY col_position) FROM jsonb_array_elements(columns) WITH ORDINALITY AS cols(col,col_position)), revision = revision + 1, updated_at = now() WHERE columns @? '$[*].items[*] ? (@.id == "services" && (@.href == "/#services" || @.href == "#services"))';
NOTIFY pgrst, 'reload schema';
COMMIT;
